  removeApp.Click+=(s,e)=>{ReadApps();foreach(var row in grid.SelectedRows.Cast<DataGridViewRow>().OrderByDescending(x=>x.Index).ToList()){var app=apps[row.Index];if(app.Session!=null)continue;apps.RemoveAt(row.Index);}RenderApps();SaveApps();};
  startApps.Click+=async(s,e)=>{if(core==null||busy||(global!=null&&global.Active))return;ReadApps();busy=true;Sync();try{int p=core.Port;foreach(var app in apps.Where(a=>a.Enabled&&a.Session==null).ToList()){var item=app;var session=new Session();item.Session=session;try{await Task.Run(()=>session.Start(item.Path,item.Arguments??"",item.Children,p));Write(Store.IsBrowser(item.Path)?"已启动原生 HTTP 代理浏览器："+Path.GetFileName(item.Path)+"；HTTP 127.0.0.1:"+(p+1)+"；请在新窗口核对出口。临时资料不共享原登录。":"已代理："+Path.GetFileName(item.Path));}catch(Exception x){Write(Path.GetFileName(item.Path)+"："+x.Message);try{if(session.ApplicationCount==0){session.Dispose();item.Session=null;}}catch{}}}RenderApps();SaveApps();}finally{busy=false;Sync();}};
  startGlobal.Click+=async(s,e)=>{if(core==null||busy)return;if(ActiveApps()>0){MessageBox.Show("请先正常退出指定程序会话，再使用全局模式。");return;}var conflicts=GlobalSupport.Conflicts();if(conflicts.Count>0){MessageBox.Show("为保持现有网络不变，全局模式未启动：\n"+String.Join("\n",conflicts)+"\n可继续使用指定程序模式。");return;}if(MessageBox.Show("将请求管理员权限，创建本工具专用 TUN，接管全局 IPv4 TCP/UDP。局域网直连，IPv6公网阻断。停止后回收自身网络变更。继续？","手动开启全局模式",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;busy=true;Sync();try{int p=core.Port;var probe=await Task.Run(()=>ProxyProbe.Test(p));if(!(bool)probe["tcp"]||!(bool)probe["udp"])throw new Exception("节点 TCP/UDP 检测未通过，未启用全局模式");global=new GlobalSession();await Task.Run(()=>global.Start(p));globalStatus.Text=global.LastStatus;Write("全局模式已启动；未修改系统代理或 FlClash 配置。");}catch(Exception x){Write(x.Message);if(global!=null)try{global.Dispose();global=null;}catch{}}finally{busy=false;Sync();}};
  stopGlobal.Click+=async(s,e)=>{if(global==null||busy)return;busy=true;Sync();try{await Task.Run(()=>global.Dispose());global=null;globalStatus.Text="● 全局模式关闭";Write("已停止全局模式。");}catch(Exception x){Write(x.Message);}finally{busy=false;Sync();}};
  timer=new System.Windows.Forms.Timer{Interval=1000};timer.Tick+=(s,e)=>{if(busy)return;bool changed=false;foreach(var a in apps.Where(x=>x.Session!=null).ToList())try{if(a.Session.ApplicationCount==0){if(++a.Idle>=3){a.Session.StopIfIdle();a.Session.Dispose();a.Session=null;changed=true;}}else a.Idle=0;}catch{}if(changed){ReadApps();RenderApps();Sync();}if(global!=null){globalStatus.Text=global.LastStatus;if(!global.Active){try{global.Dispose();}catch{}global=null;Sync();}}};timer.Start();
  FormClosing+=(s,e)=>{if(busy||ActiveApps()>0){e.Cancel=true;MessageBox.Show("请先正常退出所启动的程序，或等待当前操作完成。不会强制关闭你的工作。");return;}try{timer.Stop();if(global!=null)global.Dispose();foreach(var a in apps)if(a.Session!=null)a.Session.Dispose();if(core!=null)core.Dispose();}catch(Exception x){e.Cancel=true;Write(x.Message);timer.Start();}};
