 Label Label(string t,int x,int y,int size,bool bold){var l=new Label{Text=t,Location=new Point(x,y),AutoSize=true,Font=new Font(Font.FontFamily,size,bold?FontStyle.Bold:FontStyle.Regular),ForeColor=Color.FromArgb(35,53,77)};Controls.Add(l);return l;}
 Button Btn(string t,int x,int y,int w,Control parent=null){var b=new Button{Text=t,Location=new Point(x,y),Size=new Size(w,34)};(parent??this).Controls.Add(b);return b;}
 void RefreshCards(){nodes.Items.Clear();foreach(var c in cards)nodes.Items.Add((c.Label??c.NodeId)+" · "+c.NodeId.Substring(0,6)+(c.Version==2?" [旧版兼容]":" [需密码]"));if(cards.Count>0)nodes.SelectedIndex=0;UpdatePassword();Sync();}
 void UpdatePassword(){password.Enabled=nodes.SelectedIndex>=0&&cards[nodes.SelectedIndex].Version==3&&core==null&&!busy;}
 int ActiveApps(){int n=0;foreach(var a in apps)if(a.Session!=null)try{n+=a.Session.ApplicationCount;}catch{n++;}return n;}
 void ReadApps(){grid.EndEdit();for(int i=0;i<apps.Count;i++){apps[i].Enabled=Convert.ToBoolean(grid.Rows[i].Cells[0].Value);apps[i].Arguments=Convert.ToString(grid.Rows[i].Cells[2].Value);apps[i].Children=Convert.ToBoolean(grid.Rows[i].Cells[3].Value);}}
 void RenderApps(){grid.Rows.Clear();foreach(var a in apps)grid.Rows.Add(a.Enabled,a.Path,a.Arguments??"",a.Children,a.Session==null?"待启动":!a.Session.Ready?"启动未确认":Store.IsBrowser(a.Path)?"原生HTTP浏览器":"会话运行中");}
 void SaveApps(){Common.PrivateDir(Path.Combine(Common.Base,"profile"));File.WriteAllBytes(Path.Combine(Common.Base,"profile","apps.dpapi"),Common.Protect(Common.Json.Serialize(apps),"HomeRelayApps-v3"));}
 void Sync(){bool running=global!=null&&global.Active;nodes.Enabled=import.Enabled=remove.Enabled=port.Enabled=!busy&&core==null;connect.Enabled=!busy&&core==null&&nodes.SelectedIndex>=0;disconnect.Enabled=test.Enabled=copySs.Enabled=!busy&&core!=null;addApp.Enabled=removeApp.Enabled=grid.Enabled=!busy&&!running;startApps.Enabled=!busy&&!running&&core!=null;startGlobal.Enabled=!busy&&!running&&core!=null;stopGlobal.Enabled=!busy&&running;UpdatePassword();}
 void Write(string t){if(IsDisposed)return;if(InvokeRequired){try{BeginInvoke(new Action<string>(Write),t);}catch{}return;}if(log.TextLength>24000)log.Clear();log.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+t+Environment.NewLine);}
}
static class UnifiedProgram{
 [STAThread]static int Main(string[] a){try{if(a.Length==2&&a[0]=="--check-global"){File.WriteAllText(a[1],Common.Json.Serialize(Common.D("global_default",false,"conflicts",GlobalSupport.Conflicts(),"network_changes",false)));return 0;}
  if(a.Length==3&&a[0]=="--dump-global-config"){GlobalSupport.Verify();File.WriteAllText(a[1],Common.Json.Serialize(GlobalSupport.Config(int.Parse(a[2]),"HR3-12345678",true)));return 0;}
  if(a.Length==4&&a[0]=="--self-test"){var cfg=Common.Json.Deserialize<NodeConfig>(File.ReadAllText(a[1]));using(var c=new ConnectorCore(s=>{})){c.Start(cfg,int.Parse(a[2]));var r=ProxyProbe.Test(c.Port);File.WriteAllText(a[3],Common.Json.Serialize(r));return (bool)r["tcp"]&&(bool)r["udp"]?0:2;}}
  if(a.Length==5&&a[0]=="--unlock-test"){var card=Common.Json.Deserialize<NodeConfig>(File.ReadAllText(a[1]));var cfg=Profiles.Resolve(card,File.ReadAllText(a[2]).TrimEnd('\r','\n'));using(var c=new ConnectorCore(s=>{})){c.Start(cfg,int.Parse(a[3]));var r=ProxyProbe.Test(c.Port);File.WriteAllText(a[4],Common.Json.Serialize(r));return (bool)r["tcp"]&&(bool)r["udp"]?0:2;}}
  bool fresh;using(var m=new Mutex(true,"Local\\HomeRelayUnified-v3",out fresh)){if(!fresh){MessageBox.Show("连接器已运行，请使用已有窗口。");return 1;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new UnifiedForm());}return 0;
 }catch(Exception e){if(a.Length>0){File.WriteAllText(Path.Combine(Common.Base,"test-error.txt"),e.ToString());return 1;}MessageBox.Show(e.Message,"家宽连接器 3.0.2");return 1;}}
}
